insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$رخصة البناء (Permis de Construire)$q$,$q$Building Permit (Permis de Construire)$q$,$q$الإذن الرسمي اللازم لإنشاء أي مبنى أو إجراء توسعة أو تعديل جوهري. يُصدر بعد موافقة التنظيم المدني والبلدية المعنية ووزارة المالية. ضروري لأي بناء قانوني في لبنان.$q$,$q$The official authorization required to construct any building or to carry out an expansion or substantial modification. It is issued after approval by Urban Planning, the relevant municipality, and the Ministry of Finance. It is necessary for any lawful construction in Lebanon.$q$,$q$[{"ar": "افادة عقارية حديثة (من السجل العقاري)", "en": "A recent real estate statement (from the Land Registry)"}, {"ar": "خرائط هندسية (مسقط أفقي + مقاطع + واجهات) معدة من مهندس مرخص", "en": "Engineering drawings (floor plan, sections, and elevations) prepared by a licensed engineer"}, {"ar": "ملف نقابة المهندسين مؤشر عليه من النقابة", "en": "An Order of Engineers file endorsed by the order"}, {"ar": "اتفاقية مهندس مشروع موقعة ومسجلة بالنقابة", "en": "A project engineer agreement, signed and registered with the order"}, {"ar": "خريطة كيل تبين مناسيب الأرض", "en": "A survey map (kayl) showing the ground levels"}, {"ar": "وثيقة ملكية العقار", "en": "The property's ownership document"}, {"ar": "براءة الذمة الضريبية", "en": "A tax clearance certificate"}, {"ar": "موافقات خاصة إن وجدت (الجيش للمناطق الحساسة، وزارة السياحة للمناطق الأثرية)", "en": "Special approvals if applicable (the Army for sensitive areas, the Ministry of Tourism for archaeological areas)"}]$q$::jsonb,$q$[]$q$::jsonb,$q$المديرية العامة للتنظيم المدني + البلدية المختصة$q$,$q$من شهر إلى 4 أشهر حسب اكتمال الملف وتعقيد المشروع$q$ from municipal_service where slug=$q$mun-001$q$ on conflict (service_id,version_no) do nothing;
