insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$شهادة إشغال المبنى$q$,$q$Building Occupancy Certificate$q$,$q$وثيقة رسمية تُثبت أن المبنى المنشأ أو الموسَّع أُنجز وفق الشروط والمواصفات المذكورة في رخصة البناء، وأنه صالح للاستخدام. تُطلب لتوصيل الكهرباء والمياه والتسجيل في الأوضاع الإدارية.$q$,$q$An official document certifying that the constructed or expanded building has been completed in accordance with the conditions and specifications stated in the building permit, and that it is fit for use. It is required for connecting electricity and water and for administrative registration.$q$,$q$[{"ar": "رخصة البناء الأصلية", "en": "The original building permit"}, {"ar": "أمر المباشرة من نقابة المهندسين", "en": "The order to commence work from the Order of Engineers"}, {"ar": "تقرير إتمام الأشغال من المهندس المشرف", "en": "A report of completion of works from the supervising engineer"}, {"ar": "كشف ميداني من البلدية أو التنظيم المدني", "en": "A field inspection by the municipality or Urban Planning"}, {"ar": "إثبات الالتزام بالتصاميم المعتمدة", "en": "Proof of compliance with the approved designs"}, {"ar": "شهادات اختبار السلامة (كهرباء، حريق) في المباني التجارية", "en": "Safety test certificates (electrical, fire) for commercial buildings"}]$q$::jsonb,$q$[]$q$::jsonb,$q$البلدية المختصة + المديرية العامة للتنظيم المدني$q$,$q$شهر إلى 3 أشهر (بعد الكشف الميداني)$q$ from municipal_service where slug=$q$mun-002$q$ on conflict (service_id,version_no) do nothing;
