insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$ترخيص محل تجاري (البلدية)$q$,$q$Commercial Premises License (Municipality)$q$,$q$ترخيص لازم لفتح وتشغيل أي محل تجاري أو حرفي أو صناعي. يصدر عن البلدية التي يقع في نطاقها المحل. يختلف عن التسجيل في السجل التجاري.$q$,$q$A license required for opening and operating any commercial, craft, or industrial premises. It is issued by the municipality within whose jurisdiction the premises are located. It is distinct from registration in the commercial register.$q$,$q$[{"ar": "طلب رسمي للترخيص", "en": "An official license application"}, {"ar": "عقد إيجار المحل أو سند الملكية", "en": "The premises lease contract or the title deed"}, {"ar": "رخصة البناء للمحل أو شهادة الإشغال", "en": "The building permit for the premises or the occupancy certificate"}, {"ar": "هوية صاحب المحل", "en": "Identity of the shop owner"}, {"ar": "مستخرج السجل التجاري", "en": "A commercial register extract"}, {"ar": "موافقة المالك إن كان مستأجراً", "en": "The owner's approval if the applicant is a tenant"}, {"ar": "شهادة صحية (للمحلات الغذائية) من وزارة الصحة", "en": "A health certificate (for food establishments) from the Ministry of Public Health"}, {"ar": "موافقة وزارة الصناعة (للمنشآت الصناعية)", "en": "Approval of the Ministry of Industry (for industrial establishments)"}, {"ar": "شهادة عدم ممانعة من الجيران (لبعض النشاطات)", "en": "A no-objection certificate from neighbors (for certain activities)"}]$q$::jsonb,$q$[]$q$::jsonb,$q$البلدية المختصة + وزارة الداخلية والبلديات$q$,$q$أسبوع إلى شهر$q$ from municipal_service where slug=$q$mun-003$q$ on conflict (service_id,version_no) do nothing;
