insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$طلب خدمات البلدية (جمع النفايات، الإضاءة، الصرف الصحي)$q$,$q$Request for Municipal Services (Waste Collection, Lighting, Sanitation)$q$,$q$الخدمات البلدية الأساسية التي تتولى البلديات تأمينها للمواطنين: جمع النفايات، إضاءة الشوارع، صيانة الطرق، تصريف المياه، الصرف الصحي. الطلب يُقدم للبلدية مباشرة.$q$,$q$The basic municipal services that municipalities are responsible for providing to citizens: waste collection, street lighting, road maintenance, water drainage, and sanitation. The request is submitted directly to the municipality.$q$,$q$[{"ar": "طلب خطي أو شفهي حسب البلدية", "en": "A written or verbal request, depending on the municipality"}, {"ar": "هوية مقدم الطلب", "en": "Identity of the applicant"}, {"ar": "عنوان الخدمة المطلوبة", "en": "The address of the requested service"}, {"ar": "وثائق ملكية العقار أو عقد الإيجار (لخدمات الإشراك)", "en": "Property ownership documents or the lease contract (for connection services)"}]$q$::jsonb,$q$[]$q$::jsonb,$q$البلدية المختصة - وزارة الداخلية والبلديات$q$,$q$يتفاوت: 24 ساعة للطوارئ إلى أسابيع للمشاريع الجديدة$q$ from municipal_service where slug=$q$mun-004$q$ on conflict (service_id,version_no) do nothing;
