insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$الطعن بقرار بلدي$q$,$q$Appeal Against a Municipal Decision$q$,$q$الطريق القانوني للطعن بالقرارات البلدية التي يرى المتضرر أنها مخالفة للقانون أو تعسفية. يُقدم الطعن أمام مجلس شورى الدولة وهو المحكمة الإدارية العليا في لبنان.$q$,$q$The legal channel for appealing municipal decisions that an aggrieved party considers unlawful or arbitrary. The appeal is filed before the State Shura Council, which is the highest administrative court in Lebanon.$q$,$q$[{"ar": "استدعاء الطعن محرر من محامٍ", "en": "An appeal petition drafted by a lawyer"}, {"ar": "نسخة عن القرار البلدي المطعون فيه", "en": "A copy of the municipal decision being appealed"}, {"ar": "إثبات تبليغ القرار أو علم المتضرر به", "en": "Proof of notification of the decision or of the aggrieved party's knowledge of it"}, {"ar": "المستندات الداعمة لوجاهة الطعن", "en": "Documents supporting the merits of the appeal"}, {"ar": "وكالة خاصة لمحامٍ", "en": "A special power of attorney to a lawyer"}, {"ar": "إيصال دفع الرسوم", "en": "Fee payment receipt"}]$q$::jsonb,$q$[]$q$::jsonb,$q$مجلس شورى الدولة (القضاء الإداري)$q$,$q$من 6 أشهر إلى سنتين$q$ from municipal_service where slug=$q$mun-005$q$ on conflict (service_id,version_no) do nothing;
