insert into service_version (service_id,version_no,status,title_ar,title_en,summary_ar,summary_en,documents,steps,authority_ar,processing_time_ar) select id,1,'draft',$q$الاستعلام عن المخطط التوجيهي العام (Master Plan)$q$,$q$Inquiry about the General Master Plan$q$,$q$الاستعلام عن التصنيف العقاري لقطعة أرض ضمن المخطط التوجيهي العام (سكني، تجاري، صناعي، زراعي) ونسب الاستثمار والارتفاعات المسموحة، خطوة أساسية قبل أي رخصة بناء أو شراء عقار.$q$,$q$Inquiring about the zoning classification of a plot of land within the General Master Plan (residential, commercial, industrial, agricultural) and the permitted investment ratios and heights, an essential step before any building permit or property purchase.$q$,$q$[{"ar": "صورة عن سند ملكية الأرض أو العقار", "en": "A copy of the title deed of the land or property"}, {"ar": "طلب خطي يوضح الغرض", "en": "A written request stating the purpose"}, {"ar": "صورة هوية صاحب الطلب", "en": "A copy of the applicant's ID"}]$q$::jsonb,$q$[]$q$::jsonb,$q$المديرية العامة للتنظيم المدني — البلدية المختصة$q$,$q$أسبوع إلى أسبوعين$q$ from municipal_service where slug=$q$proc-001$q$ on conflict (service_id,version_no) do nothing;
